import stylesText from './provenance-badge.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';

const styles = cssStyleSheet(stylesText);

/** Where a line's food comes from, as the AI drafts and the library's "to check" list show it. */
export const PROVENANCE_KINDS = ['library', 'off', 'ai', 'label', 'differs', 'added', 'meal'] as const;
export type ProvenanceKind = typeof PROVENANCE_KINDS[number];

const LABELS: Record<ProvenanceKind, string> = {
    library: 'library',
    off: 'Open Food Facts',
    ai: 'new · AI',
    label: 'label photo',
    differs: 'differs from library',
    added: 'added',
    meal: 'meal',
};

const template = document.createElement('template');
template.innerHTML = `<span class="badge" part="badge"></span>`;

/**
 * Story 420 — `<provenance-badge kind="ai">`: a small labelled tag. An unknown kind is a bug in
 * the caller and renders its raw value, so it shows up instead of vanishing.
 */
export class ProvenanceBadge extends HTMLElement {
    static get observedAttributes() { return ['kind']; }

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private render(): void {
        const kind = this.getAttribute('kind') ?? '';
        const badge = this.shadowRoot!.querySelector('.badge') as HTMLElement;
        badge.textContent = (PROVENANCE_KINDS as readonly string[]).includes(kind) ? LABELS[kind as ProvenanceKind] : `?${kind}`;
        badge.dataset.kind = kind;
    }
}

if (!customElements.get('provenance-badge')) {
    customElements.define('provenance-badge', ProvenanceBadge);
}
