import {
    LINE_NUTRIENTS,
    lineNutrition,
    rescaleNutrition,
    type FoodBaseUnit,
    type FoodItem,
    type LineInput,
    type LineNutrient,
    type LineNutrition,
    type LogLine,
    type MealIngredientWithFoodItem,
    type NewFoodItem,
    type NutritionBasis,
} from '@motivation/shared';

/**
 * Story 420 (418 #1) — one line as every nutrition element shows it: a meal's ingredient, a
 * logged line, or a draft's line. Where its nutrition comes from is the only difference:
 * - `food` — from the food's density (a meal ingredient, a line not saved yet);
 * - `snapshot` — a logged line's snapshot at the amount it was logged, rescaled (418 #4).
 * An `override` replaces individual nutrients (story 368).
 */
export interface LineView {
    /** Stable within a list: a line's id, or a client key for one not saved yet. */
    key: string;
    name: string;
    unit: FoodBaseUnit;
    amount: number;
    imagePath: string | null;
    basis:
        | { kind: 'food'; food: NutritionBasis }
        | { kind: 'snapshot'; nutrition: LineNutrition; amount: number };
    override?: Partial<LineNutrition>;
    /** What the line saves as: its food, or an inline new food (418 #7). */
    source: { food_item_id: string } | { new_food_item: NewFoodItem } | { line_id: string };
    /** A provenance word for `<provenance-badge>`, when the line has one to show. */
    badge?: string;
}

/** The one place a view's nutrition is computed — on top of `lineNutrition` (shared). */
export function viewNutrition(view: LineView): LineNutrition {
    const base = view.basis.kind === 'food'
        ? lineNutrition(view.basis.food, view.amount)
        : rescaleNutrition(view.basis.nutrition, view.basis.amount, view.amount);
    if (!view.override) return base;
    const out = { ...base };
    for (const n of LINE_NUTRIENTS) {
        const v = view.override[n];
        if (v !== undefined) out[n] = v;
    }
    return out;
}

export function withAmount(view: LineView, amount: number): LineView {
    // An override is a statement about the amount it was made at; it scales with the line.
    const override = view.override === undefined ? undefined : scalePartial(view.override, amount / view.amount);
    return { ...view, amount, override };
}

function scalePartial(partial: Partial<LineNutrition>, factor: number): Partial<LineNutrition> {
    const out: Partial<LineNutrition> = {};
    for (const [n, v] of Object.entries(partial) as Array<[LineNutrient, number | null]>) out[n] = v === null ? null : v * factor;
    return out;
}

export function foodLineView(food: FoodItem, amount: number, key: string = food.id): LineView {
    return {
        key, name: food.display_name, unit: food.base_unit, amount, imagePath: food.image_path,
        basis: { kind: 'food', food }, source: { food_item_id: food.id },
    };
}

export function newFoodLineView(food: NewFoodItem, amount: number, key: string): LineView {
    return {
        key, name: food.display_name, unit: food.base_unit, amount, imagePath: food.image_path ?? null,
        basis: { kind: 'food', food }, source: { new_food_item: food },
    };
}

export function ingredientView(ingredient: MealIngredientWithFoodItem): LineView {
    return foodLineView(ingredient.food_item, ingredient.amount, ingredient.id);
}

export function logLineView(line: LogLine): LineView {
    const nutrition: LineNutrition = {
        calories: line.calories, protein_g: line.protein_g, carbs_g: line.carbs_g, fat_g: line.fat_g,
        fiber_g: line.fiber_g, sugar_g: line.sugar_g, sodium_mg: line.sodium_mg,
    };
    return {
        key: line.id, name: line.food_name, unit: line.unit, amount: line.amount, imagePath: line.image_path,
        basis: { kind: 'snapshot', nutrition, amount: line.amount }, source: { line_id: line.id },
    };
}

/** What the API takes for this view (418 #7): its line, its food, or its inline new food. */
export function toLineInput(view: LineView): LineInput {
    const input: LineInput = { amount: view.amount };
    if ('line_id' in view.source) input.id = view.source.line_id;
    else if ('food_item_id' in view.source) input.food_item_id = view.source.food_item_id;
    else input.new_food_item = view.source.new_food_item;
    if (view.override !== undefined) input.nutrition = view.override;
    return input;
}

/** Unit as the eye reads it: g, ml, or pc. */
export function unitLabel(unit: FoodBaseUnit): string {
    return unit === 'piece' ? 'pc' : unit;
}
